-- Data for club_settings (1 rows)
INSERT INTO `club_settings` (`id`, `club_name`, `tagline`, `logo_url`, `favicon_url`, `banner_url`, `about`, `history`, `mission`, `vision`, `objectives`, `email`, `phone`, `address`, `social_links`, `updated_at`) VALUES
(1, 'NIRVANA', 'LEARN • EXPLORE • GROW', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=300&q=80', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=64&q=80', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?auto=format&fit=crop&w=1600&q=80', 'NIRVANA is a student club that brings together curious minds, creative thinkers and passionate learners. We provide a platform for students to explore new ideas, work on meaningful projects, participate in events and build a strong community. Our goal is to help every member learn, collaborate, explore opportunities and grow — both personally and professionally.', 'Established in 2018 by five enthusiastic undergraduate students, the club has grown from a humble lab corner into a nationally recognized innovation hub with over 150+ active members and prestigious international awards.', 'A student club dedicated to uplifting underprivileged communities through education, lifestyle lessons, primary care, cultural values and opportunities.', 'To emerge as a premier collegiate research and innovation body, bridging academic excellence with cutting-edge industry technology.', '["Promote hands-on engineering, robotics, and creative problem-solving.","Participate in national and international technical symposiums and competitions.","Mentor junior members through structured workshops, bootcamps, and hackathons.","Build industry-standard open source systems and autonomous robots.","Foster an active, supportive alumni network across global technology leaders."]', 'contact@apexclub.org', '+1 (555) 234-5678', 'Technology Innovation Center, Block 4, University Campus, Innovation Way', '{"linkedin":"https://linkedin.com/company/apex-robotics-club","github":"https://github.com/apex-robotics","twitter":"https://twitter.com/ApexRobotics","instagram":"https://instagram.com/apex_robotics","youtube":"https://youtube.com/@ApexRobotics"}', '2026-10-05 14:37:16');

