(1, 'ARC-2025-001', 'Aarav Sharma', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=400&q=80', 'Club President', 'Core Executive', '2023-08-10', 'Senior Undergraduate passionate about autonomous navigation, ROS2, and team leadership. Guided 4 competition teams to national podiums.', '["ROS2","Python","C++","SLAM","Leadership","Strategic Planning"]', '["National Robocon 2024 Team Captain","Best Innovation Award IEEE 2023","Published Research Paper on LiDAR Odometry"]', 'active', 'data:image/png;base64,', 1, 1, '2026-10-05 13:33:12', '2026-10-05 13:33:12'),
(2, 'ARC-2025-002', 'Elena Rostova', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=400&q=80', 'Vice President & Technical Lead', 'Autonomous Systems', '2023-09-01', 'Specialist in Computer Vision and Deep Learning for robotics manipulation. Leading our vision sensor fusion architecture.', '["PyTorch","Computer Vision","CUDA","OpenCV","Embedded Linux"]', '["1st Place in Vision Track at HackAI 2024","Author of open-source YOLO-depth pipeline"]', 'active', 'data:image/png;base64,', 1, 2, '2026-10-05 13:33:12', '2026-10-05 13:33:12'),
(3, 'ARC-2025-003', 'David Chen', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80', 'Head of Mechanical & CAD', 'Hardware Design', '2023-11-15', 'Mechanical engineering enthusiast who loves rapid prototyping, CNC machining, generative design, and high-torque drone chassis.', '["SolidWorks","Fusion 360","FEA Simulation","Rapid 3D Prototyping","Aerodynamics"]', '["Lightweight Carbon-Fiber Chassis patent pending","University Maker of the Year 2024"]', 'active', 'data:image/png;base64,', 1, 3, '2026-10-05 13:33:12', '2026-10-05 13:33:12'),
(4, 'ARC-2026-004', 'Sophia Martinez', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=400&q=80', 'Firmware & Electronics Lead', 'Embedded Systems', '2024-01-20', 'Hardware engineer with focus on custom STM32 and ESP32 multi-layer PCB design, CAN bus protocol, and power distribution units.', '["Altium Designer","KiCAD","Embedded C","CAN Bus","RTOS","Power Systems"]', '["Designed 4-layer motor driver PCB with 98% power efficiency","Embedded Systems Hackathon Winner"]', 'active', 'data:image/png;base64,', 1, 4, '2026-10-05 13:33:12', '2026-10-05 13:33:12'),
