(6, 'ARC-2024-006', 'Marcus Vance', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&q=80', 'Research Associate', 'Robotics & AI', '2022-09-12', 'Former sensor team member currently on leave for industrial co-op internship at automotive research laboratory.', '["C++","MATLAB","State Estimation","Kalman Filters"]', '["Sensors Track Finalist 2023"]', 'inactive', 'data:image/png;base64,', 0, 6, '2026-10-05 13:33:12', '2026-10-05 13:33:12'),
