-- Data for events (5 rows)
INSERT INTO `events` (`id`, `title`, `date`, `location`, `image_url`, `short_description`, `description`, `organizer`, `status`, `registration_link`, `created_at`, `updated_at`, `time`, `category`, `event_type`, `delivery_mode`, `speakers`, `registration_url`) VALUES
(1, 'Autonomous Systems Symposium & Poster Exhibition', '2026-11-12', 'Main Seminar Hall, Technology Block', 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=800&q=80', 'A full-day technical presentation session where student teams exhibit research findings in robotics perception and control.', 'A day-long interactive symposium bringing together students and researchers to present papers, posters, and live prototypes in LiDAR SLAM, state estimation, and reinforcement learning. A jury of senior faculty members evaluates presentations with prize distribution at the valedictory session.', 'Academic Events Committee & Faculty Advisors', 'upcoming', 'https://forms.google.com', '2026-10-05 14:03:41', '2026-10-05 14:03:41', '09:30 AM - 05:00 PM', 'Robotics & Hardware', 'Symposium', 'Offline', 'Dr. K. S. Rao (Professor of Autonomous Systems), Elena Rostova (VP Technical Lead)', NULL),
(2, 'Hands-on ROS2 & Gazebo Simulation Workshop', '2026-10-25', 'Robotics Computing Lab 402', 'https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&w=800&q=80', 'An intensive weekend tutorial covering ROS2 nodes, pub-sub architectures, and URDF robot modeling in simulation.', 'This hands-on workshop walks participants through configuring ROS2 Humble, creating custom package architectures, writing C++ and Python nodes, and importing CAD models into Gazebo for real-time physics simulation.', 'Software & Simulation Sub-team', 'upcoming', 'https://forms.google.com', '2026-10-05 14:03:41', '2026-10-05 14:03:41', '02:00 PM - 06:00 PM', 'AI & Computer Vision', 'Workshop', 'Hybrid', 'Aarav Sharma (President), James Thornton (Tesla Autopilot Alumni)', NULL),
(3, 'Pan-Collegiate Hardware Hackathon (Hack-A-Bot)', '2025-11-18', 'Innovation Center Ground Floor', 'https://images.unsplash.com/photo-1504384308090-c894fdcc538d?auto=format&fit=crop&w=800&q=80', 'A 36-hour non-stop engineering sprint challenging 24 teams to build obstacle-avoiding mobile robots using standardized kits.', 'Participants were provided with microcontrollers, motor drivers, sensor arrays, and raw acrylic sheets to fabricate functional autonomous rovers. Over 100 students from 12 institutes competed across 3 qualifying rounds.', 'Apex Robotics Club Executive Board', 'past', '', '2026-10-05 14:03:41', '2026-10-05 14:03:41', '36-Hour Sprint (Starts 10:00 AM)', 'Embedded & IoT', 'Hackathon', 'Offline', 'Sophia Martinez (Firmware Lead), David Chen (CAD Lead)', NULL),
(4, 'Guest Lecture: Advances in Planetary Rover Locomotion', '2025-09-08', 'Auditorium Hall B', 'https://images.unsplash.com/photo-1475721027785-f74eccf877e2?auto=format&fit=crop&w=800&q=80', 'An academic lecture analyzing rocker-bogie mechanisms and extraterrestrial terrain traversal.', 'A distinguished guest lecture analyzing the mechanical design considerations for Martian soil traversal, slip compensation algorithms, and autonomous path planning on steep inclines.', 'Department Faculty Advisor & Club Outreach', 'past', '', '2026-10-05 14:03:41', '2026-10-05 14:03:41', '04:00 PM - 05:30 PM', 'Aerospace Mechanisms', 'Guest Lecture', 'Online', 'Ananya Deshmukh (NASA JPL Alumni & Mechanisms Engineer)', NULL),
(6, 'Annual Autonomous Drone Design & Flight Sprint', '2026-10-05', 'Aeronautics Arena & High-Bay Ground', 'https://images.unsplash.com/photo-1527977966376-1c8408f9f108?auto=format&fit=crop&w=800&q=80', 'Live collegiate quadcopter endurance, obstacle slalom, and autonomous landing trials currently underway.', 'Teams from various engineering departments are running live autonomous flight tests. Quadcopters navigate through high-precision LiDAR beacons, test payload drop mechanisms, and execute dynamic PID tuning under the evaluation of the senior technical council.', 'Apex Drone Working Group', 'live', 'https://forms.google.com', '2026-10-05 14:19:35', '2026-10-05 14:19:35', '10:00 AM - 07:00 PM (In Progress)', 'Robotics & Hardware', 'Competition', 'Offline', 'Elena Rostova, David Chen, Faculty Observers', 'https://forms.google.com');

